package com.cenedu.backend.ai.problem.adapter;
import static org.assertj.core.api.Assertions.*; import com.cenedu.backend.ai.problem.render.*; import com.cenedu.backend.domain.problem.authoring.asset.*; import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.global.common.enums.QuestionType; import java.nio.file.*; import java.util.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.io.TempDir;
class LocalDraftAssetProductionAdapterTest { @TempDir Path root; @Test void delegatesTypedPlanAndWritesAtomicSvg() throws Exception {var spec=new NumberLineDiagramSpecV1(1,"FIG",DiagramKind.NUMBER_LINE,new DiagramViewport(640,180,16),new DiagramStyle("#000000","#FFFFFF","#FF0000",1,"sans-serif",12),"A","B","C",List.of(),List.of(),false,false);var plan=new GeneratedAssetPlan("FIG",com.cenedu.backend.domain.problem.entity.enums.AssetRole.FIGURE,AssetProductionMode.STRUCTURED_RENDER,AssetOutputFormat.SVG,"figure",new AssetGenerationSpecification(1,"figure",List.of(),List.of(),Map.of(),spec));var a=new LocalDraftAssetProductionAdapter(root.toString(),new SafeSvgSanitizer(),new ProblemDiagramRenderer(new SafeSvgSanitizer()));var artifact=a.produce(plan,new AssetProductionContext(7L,2,QuestionType.SHORT_INPUT));assertThat(artifact.status()).isEqualTo(DraftAssetStatus.READY);assertThat(root.resolve(artifact.draftStorageKey())).exists();} }
